void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  //uv += (vec2(1.0)/uTexSize) / 2.0;
uv0 = uv;
//uv mit Wasseroberflaeche modulieren
dz1.x = GetBuf(uv+pix*vec2( 1.0 , 0.0 )) - GetBuf(uv+pix*vec2(-1, 0.0 ));
dz1.y = GetBuf(uv+pix*vec2( 0.0 , 1.0 )) - GetBuf(uv+pix*vec2( 0.0 ,-1));
uv += dz1 * clamp01(1.0 - GetBuf(uv0))*.5;
float k1 =1;
dz.x = pow(GetPixel(uv+pix*vec2( 1.0 , 0.0 )).b,k1) - pow(GetPixel(uv+pix*vec2(-1, 0.0 )).b,k1);
dz.y = pow(GetPixel(uv+pix*vec2( 0.0 , 1.0 )).b,k1) - pow(GetPixel(uv+pix*vec2( 0.0 ,-1)).b,k1);
//Untergrund
ret = texture(sampler_rand00,uv +dz1)  *.5;
//farbiger Glanz und Spiegelung der Sonne in der Wasseroberflaeche
uv1 = uv-.1+dz1 * 8.0;
vec3 refl = .1/vec3 (length(uv1+dz*.6),length(uv1+dz), length(uv1+dz*2.6) );
//Fische subtrahieren; einige schwimmen "unter" der Oberflaeche
ret += refl - GetPixel(uv0).b*.2 - GetPixel(.8-uv).b*.2;
//ret = GetPixel(uv).r;
  fragColor = vec4(ret, 1.0);
}

